// TD Bank Credit Card CSV Parser
// Expected format: Date,Description,Amount,[Credit Column]
// Date format: MM/DD/YYYY
// Amount: Debits are positive, Credits have value in 4th column
// No header row in the CSV

import { BaseCSVParser } from './BaseCSVParser';
import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';

export class TDBankParser extends BaseCSVParser {
	parse(csvContent: string): CSVParseResult {
		const transactions: ParsedTransaction[] = [];
		const errors: string[] = [];

		try {
			csvContent = this.removeBOM(csvContent);
			const rows = this.parseCSV(csvContent);

			if (rows.length < 1) {
				errors.push('CSV file is empty or has no data rows');
				return { transactions, errors };
			}

			// TD Bank CSV has no header row, starts directly with data
			// Format: Date,Description,Amount[,Credit Amount]
			// If there are 4 columns and the 4th has a value, it's a credit (positive)
			// If there are 3 columns or 4th column is empty, the amount in column 3 is a debit (negative)

			for (let i = 0; i < rows.length; i++) {
				const row = rows[i];
				if (row.length < 3) continue; // Skip incomplete rows

				const dateStr = row[0]?.trim();
				const description = row[1]?.trim();
				const debitAmountStr = row[2]?.trim();
				const creditAmountStr = row.length > 3 ? row[3]?.trim() : '';

				// Skip empty rows
				if (!dateStr && !description && !debitAmountStr) continue;

				// Parse date
				const transaction_date = this.parseDate(dateStr);
				if (!transaction_date) {
					errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
					continue;
				}

				// Determine amount (credit or debit)
				let rawAmount: number | null = null;
				if (creditAmountStr) {
					// It's a credit (deposit/refund) - originally positive
					rawAmount = this.parseAmount(creditAmountStr);
				} else if (debitAmountStr) {
					// It's a debit (expense/purchase) - make negative for normalization
					const parsedDebit = this.parseAmount(debitAmountStr);
					if (parsedDebit !== null) {
						rawAmount = -Math.abs(parsedDebit); // Ensure it's negative
					}
				}

				if (rawAmount === null) {
					errors.push(
						`Row ${i + 1}: Invalid amount (debit: "${debitAmountStr}", credit: "${creditAmountStr}")`
					);
					continue;
				}

				// TD Bank uses negative for expenses — keep as-is (#{#trn2e})
