	// #{#wsp2b} Transaction parsing
	parse(csvContent: string): CSVParseResult {
		const transactions: ParsedTransaction[] = [];
		const errors: string[] = [];

		const cleanContent = this.removeBOM(csvContent);
		const rows = this.parseCSV(cleanContent);

		// Skip header row and parse data rows
		for (let i = 1; i < rows.length; i++) {
			const row = rows[i];
			const rowNumber = i + 1;

			// Skip empty rows
			if (!row || row.every((cell) => !cell?.trim())) {
