				if (fundsOutStr) {
					const parsedOut = this.parseAmount(fundsOutStr);
					if (parsedOut !== null) {
						rawAmount = -Math.abs(parsedOut); // Ensure it's negative (expense)
					}
				} else if (fundsInStr) {
					const parsedIn = this.parseAmount(fundsInStr);
					if (parsedIn !== null) {
						rawAmount = Math.abs(parsedIn); // Ensure it's positive (deposit)
					}
				}

				if (rawAmount === null) {
					errors.push(`Row ${i + 1}: Invalid amount (out: "${fundsOutStr}", in: "${fundsInStr}")`);
					continue;
				}

				// Simplii uses negative for expenses — keep as-is (#{#trn2f})
				const amount = this.normalizeAmount(rawAmount, false);

				// Validate description
				if (!description) {
					errors.push(`Row ${i + 1}: Missing transaction details/description`);
					continue;
				}

				transactions.push({
					transaction_date,
					vendor_name: description,
					amount
				});
			}
		} catch (e: any) {
			errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
		}

		return { transactions, errors };
	}

	validateFormat(csvContent: string): boolean {
		try {
			csvContent = this.removeBOM(csvContent);
			const rows = this.parseCSV(csvContent);
			if (rows.length === 0) return false;

			const header = rows[0];
			// Check for Simplii-specific columns
			const expectedColumns = ['date', 'transaction details', 'funds out', 'funds in'];
			return this.hasExpectedColumns(header, expectedColumns);
		} catch {
			return false;
		}
	}
}

