import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { TDBankParser } from '../TDBankParser';

describe('TDBankParser', () => {
	const parser = new TDBankParser();

	// Helper to load CSV files from resources
	const loadCSV = (filename: string): string => {
		const filePath = join(process.cwd(), 'resources', filename);
		return readFileSync(filePath, 'utf-8');
	};

	describe('validateFormat', () => {
		it('should validate correct TD Bank CSV format', () => {
			const csv = loadCSV('TDBankSample.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should validate format with 4 columns (credit transactions)', () => {
			const csvWithCredit = `06/11/2024,Store 1,,23.15
06/10/2024,No Better,89.19,`;
			expect(parser.validateFormat(csvWithCredit)).toBe(true);
		});

		it('should reject invalid CSV format', () => {
			const invalidCSV = `Description,Type,Card Holder Name,Date,Time,Amount
Test Store,PURCHASE,MARK,06/01/2024,11:59 PM,-100.00`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should reject empty CSV', () => {
			expect(parser.validateFormat('')).toBe(false);
		});

		it('should reject CSV with too few columns', () => {
			const invalidCSV = `06/26/2024,New Store 2`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should reject CSV with too many columns', () => {
			const invalidCSV = `06/26/2024,New Store 2,180.74,10.00,extra`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});
	});

	describe('parse', () => {
		it('should parse sample data correctly (#{#trn2e})', () => {
			const csv = loadCSV('TDBankSample.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(42);

			// Check first transaction (debit, stays negative)
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-06-26',
				vendor_name: 'New Store 2',
				amount: -180.74 // Debit (expense), negative = expense
			});

			// Check last transaction (debit, stays negative)
			expect(result.transactions[41]).toEqual({
				transaction_date: '2024-06-06',
				vendor_name: 'Store C',
				amount: -22.6 // Debit (expense), negative = expense
			});
		});

		it('should keep debit transactions as negative amounts (#{#trn2e})', () => {
			const csv = `06/26/2024,Test Store,100.50,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(-100.5); // Debit stays negative
		});

		it('should keep credit transactions as positive amounts (#{#trn2e})', () => {
			const csv = `06/11/2024,Store 1,,23.15`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-06-11',
				vendor_name: 'Store 1',
				amount: 23.15 // Credit stays positive
			});
		});

		it('should keep debit amounts without decimals as negative (#{#trn2e})', () => {
			const csv = `06/24/2024,Store C,85,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-85); // Debit stays negative
		});

		it('should parse dates in MM/DD/YYYY format', () => {
			const csv = `12/31/2023,Test Store,100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2023-12-31');
		});

		it('should handle dates with single digit month/day', () => {
			const csv = `1/5/2024,Test Store,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-01-05');
		});

		it('should report errors for invalid dates', () => {
			const csv = `invalid-date,Test Store,100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid date format');
		});

		it('should report errors for invalid amounts', () => {
			const csv = `06/01/2024,Test Store,not-a-number,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should report errors for missing vendor name', () => {
			const csv = `06/01/2024,,100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Missing vendor name');
		});

		it('should handle empty CSV', () => {
			const result = parser.parse('');

			expect(result.transactions).toEqual([]);
			expect(result.errors.length).toBeGreaterThan(0);
		});

		it('should skip incomplete rows', () => {
			const csv = `06/01/2024,Test Store,100.00,
06/02/2024,Incomplete
06/03/2024,Another Store,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.transactions[0].vendor_name).toBe('Test Store');
			expect(result.transactions[1].vendor_name).toBe('Another Store');
		});

		it('should skip empty rows', () => {
			const csv = `06/01/2024,Test Store,100.00,

06/02/2024,Another Store,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('TDBankSample.csv');
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(42);
			expect(result.errors).toEqual([]);
		});

		it('should handle mixed debit and credit transactions (#{#trn2e})', () => {
			const csv = `06/01/2024,Store A,100.00,
06/02/2024,Store B,,50.00
06/03/2024,Store C,75.00,
06/04/2024,Store D,,25.00`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(4);
			expect(result.transactions[0].amount).toBe(-100.0); // Debit, stays negative
			expect(result.transactions[1].amount).toBe(50.0); // Credit, stays positive
			expect(result.transactions[2].amount).toBe(-75.0); // Debit, stays negative
			expect(result.transactions[3].amount).toBe(25.0); // Credit, stays positive
		});
	});
});

