import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { WealthSimpleParser } from '../WealthSimpleParser';

describe('WealthSimpleParser', () => {
	const parser = new WealthSimpleParser();

	// Helper to load CSV files from resources
	const loadCSV = (filename: string): string => {
		const filePath = join(process.cwd(), 'resources', filename);
		return readFileSync(filePath, 'utf-8');
	};

	describe('validateFormat - #{#wsp2a}', () => {
		it('should validate correct Wealth Simple CSV format', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","LCBO/RAO #0556","18.9","CAD"';
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should reject invalid CSV format (missing columns)', () => {
			const invalidCSV = '"transaction_date","amount"\n"2025-12-13","18.9"';
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should handle case-insensitive headers', () => {
			const csv =
				'"TRANSACTION_DATE","POST_DATE","TYPE","DETAILS","AMOUNT","CURRENCY"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","18.9","CAD"';
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should reject empty CSV', () => {
			expect(parser.validateFormat('')).toBe(false);
		});

		it('should handle CSV with BOM', () => {
			const csv =
				'\uFEFF"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","18.9","CAD"';
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should reject CSV with only some required columns', () => {
			const invalidCSV =
				'"transaction_date","post_date","type"\n' + '"2025-12-13","2025-12-14","Purchase"';
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should validate actual WealthSimple.csv sample file', () => {
			const csv = loadCSV('WealthSimple.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});
	});

	describe('parse - #{#wsp2b}', () => {
		it('should parse valid Wealth Simple CSV', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","LCBO/RAO #0556","-18.9","CAD"\n' +
				'"2025-12-22","2025-12-23","Purchase","BULK BARN #507","-18.27","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.errors).toHaveLength(0);

			expect(result.transactions[0]).toEqual({
				transaction_date: '2025-12-13',
				vendor_name: 'LCBO/RAO #0556',
				amount: -18.9
			});

			expect(result.transactions[1]).toEqual({
				transaction_date: '2025-12-22',
				vendor_name: 'BULK BARN #507',
				amount: -18.27
			});
		});

		it('should handle invalid date', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"invalid-date","2025-12-14","Purchase","TEST","18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(0);
			expect(result.errors).toHaveLength(1);
			expect(result.errors[0]).toContain('Invalid transaction_date');
		});

		it('should handle invalid amount', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","invalid","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(0);
			expect(result.errors).toHaveLength(1);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should handle missing vendor name', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","","18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(0);
			expect(result.errors).toHaveLength(1);
			expect(result.errors[0]).toContain('Missing details/vendor name');
		});

		it('should handle incomplete row', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(0);
			expect(result.errors).toHaveLength(1);
			expect(result.errors[0]).toContain('Incomplete row');
		});

		it('should skip empty rows', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","-18.9","CAD"\n' +
				',,,,,,\n' +
				'"2025-12-22","2025-12-23","Purchase","TEST2","-18.27","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.errors).toHaveLength(0);
		});

		it('should handle BOM', () => {
			const csv =
				'\uFEFF"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","-18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.errors).toHaveLength(0);
			expect(result.transactions[0].vendor_name).toBe('TEST');
		});

		it('should accumulate multiple errors', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"invalid-date","2025-12-14","Purchase","TEST","18.9","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","","18.9","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","invalid","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(0);
			expect(result.errors).toHaveLength(3);
			expect(result.errors[0]).toContain('Invalid transaction_date');
			expect(result.errors[1]).toContain('Missing details/vendor name');
			expect(result.errors[2]).toContain('Invalid amount');
		});

		it('should continue parsing after errors', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"invalid-date","2025-12-14","Purchase","TEST","-18.9","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","VALID TRANSACTION","-18.9","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","","-18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.errors).toHaveLength(2);
			expect(result.transactions[0].vendor_name).toBe('VALID TRANSACTION');
		});

		it('should handle quoted fields with commas', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","STORE, LOCATION #123","-18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.errors).toHaveLength(0);
			expect(result.transactions[0].vendor_name).toBe('STORE, LOCATION #123');
		});

		it('should parse amounts with varying decimal precision', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST1","-18.9","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST2","-18.27","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST3","-100","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(3);
			expect(result.errors).toHaveLength(0);
			expect(result.transactions[0].amount).toBe(-18.9);
			expect(result.transactions[1].amount).toBe(-18.27);
			expect(result.transactions[2].amount).toBe(-100);
		});

		it('should enforce sign based on type column regardless of CSV sign - #{#wsp1a}', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","EXPENSE","50.00","CAD"\n' +
				'"2025-12-13","2025-12-14","Purchase","EXPENSE2","-50.00","CAD"\n' +
				'"2025-12-13","2025-12-14","Refund","REFUND","25.00","CAD"\n' +
				'"2025-12-13","2025-12-14","Payment","PAYMENT","-100.00","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(4);
			expect(result.errors).toHaveLength(0);
			// Purchase → always negative, regardless of CSV sign
			expect(result.transactions[0].amount).toBe(-50.0);
			expect(result.transactions[1].amount).toBe(-50.0);
			// Refund/Payment → always positive
			expect(result.transactions[2].amount).toBe(25.0);
			expect(result.transactions[3].amount).toBe(100.0);
		});
	});

	describe('Integration test - #{#wsp4b}', () => {
		it('should parse actual WealthSimple.csv sample file', () => {
			const csv = loadCSV('WealthSimple.csv');
			const result = parser.parse(csv);

			expect(result.errors).toHaveLength(0);
			expect(result.transactions).toHaveLength(3);

			// Verify first transaction
			expect(result.transactions[0]).toEqual({
				transaction_date: '2025-12-13',
				vendor_name: 'LCBO/RAO #0556',
				amount: -18.9
			});

			// Verify second transaction
			expect(result.transactions[1]).toEqual({
				transaction_date: '2025-12-22',
				vendor_name: 'BULK BARN #507 KANATA',
				amount: -18.27
			});

			// Verify third transaction
			expect(result.transactions[2]).toEqual({
				transaction_date: '2025-12-22',
				vendor_name: 'BULK BARN #507 KANATA',
				amount: -18.86
			});
		});
	});

	describe('Date parsing', () => {
		it('should parse YYYY-MM-DD date format', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","-18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].transaction_date).toBe('2025-12-13');
		});

		it('should reject invalid date formats', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"12/13/2025","2025-12-14","Purchase","TEST","-18.9","CAD"';

			const result = parser.parse(csv);

			// BaseCSVParser might handle this format, but testing error handling
			expect(result.transactions.length + result.errors.length).toBeGreaterThan(0);
		});
	});

	describe('Edge cases', () => {
		it('should handle CSV with only header row', () => {
			const csv = '"transaction_date","post_date","type","details","amount","currency"';
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(0);
			expect(result.errors).toHaveLength(0);
		});

		it('should handle whitespace in vendor names', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","  STORE NAME  ","-18.9","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			// BaseCSVParser should trim whitespace
			expect(result.transactions[0].vendor_name).toBe('STORE NAME');
		});

		it('should handle zero amounts', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","TEST","0.00","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(0);
		});

		it('should handle large amounts', () => {
			const csv =
				'"transaction_date","post_date","type","details","amount","currency"\n' +
				'"2025-12-13","2025-12-14","Purchase","EXPENSIVE","-9999.99","CAD"';

			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(-9999.99);
		});
	});
});

