import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { AmexParser } from '../AmexParser';

describe('AmexParser', () => {
	const parser = new AmexParser();

	// Helper to load CSV files from resources
	const loadCSV = (filename: string): string => {
		const filePath = join(process.cwd(), 'resources', filename);
		return readFileSync(filePath, 'utf-8');
	};

	describe('validateFormat', () => {
		it('should validate correct Amex CSV format', () => {
			const csv = loadCSV('Amex-Test.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should reject invalid CSV format (no Amex identifier)', () => {
			const invalidCSV = `Date,Description,Amount
01/01/2024,Store,100.00`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should reject empty CSV', () => {
			expect(parser.validateFormat('')).toBe(false);
		});

		it('should reject CSV without data header row', () => {
			const invalidCSV = `American Express
Some other row
More data`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('Amex-Test.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});
	});

	describe('parse', () => {
		it('should parse sample data correctly', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(14);

			// Check first transaction
			expect(result.transactions[0]).toEqual({
				transaction_date: '2025-05-31',
				vendor_name: 'Alcohol',
				amount: -33.2
			});

			// Check last transaction
			expect(result.transactions[13]).toEqual({
				transaction_date: '2025-05-17',
				vendor_name: 'Online',
				amount: -137.15
			});
		});

		it('should skip header rows before data', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// Should not include summary rows or empty rows
			expect(result.transactions.every((t) => t.vendor_name !== 'Summary')).toBe(true);
			expect(result.transactions.every((t) => t.vendor_name !== 'Charges & Adjustments')).toBe(
				true
			);
		});

		it('should handle amounts with commas', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// The sample file has amounts without commas in the data section
			// but the summary section has commas - verify data parsing works
			expect(result.transactions.every((t) => !isNaN(t.amount))).toBe(true);
		});

		it('should handle amounts with dollar signs', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// All amounts should be parsed correctly despite dollar signs
			expect(result.transactions[0].amount).toBe(-33.2);
			expect(result.transactions[1].amount).toBe(-41.97);
		});

		it('should parse dates in DD-MMM-YY format', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store,$100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2025-05-31');
		});

		it('should handle dates with full month names', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
27-May-25,27-May-25,Test Store,$50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2025-05-27');
		});

		it('should report errors for invalid dates', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
invalid-date,01 Jun. 2025,Test Store,$100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid date format');
		});

		it('should report errors for invalid amounts', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store,not-a-number,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should report errors for missing description', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,,$100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Missing vendor name');
		});

		it('should handle empty CSV', () => {
			const result = parser.parse('');

			expect(result.transactions).toEqual([]);
			expect(result.errors.length).toBeGreaterThan(0);
		});

		it('should skip incomplete rows', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store,$100.00,
Incomplete Row
01-Jun-25,02 Jun. 2025,Another Store,$50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.transactions[0].vendor_name).toBe('Test Store');
			expect(result.transactions[1].vendor_name).toBe('Another Store');
		});

		it('should skip empty rows', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store,$100.00,

01-Jun-25,02 Jun. 2025,Another Store,$50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(14);
			expect(result.errors).toEqual([]);
		});

		it('should handle amounts with spaces', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store, $100.00 ,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-100.0);
		});

		it('should handle decimal amounts', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// Check various decimal amounts
			expect(result.transactions[0].amount).toBe(-33.2);
			expect(result.transactions[1].amount).toBe(-41.97);
			expect(result.transactions[2].amount).toBe(-16.09);
		});

		it('should handle all transactions as negative amounts (credit card charges = expenses)', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// Amex charges are all negative (negative = expense)
			expect(result.transactions.every((t) => t.amount < 0)).toBe(true);
		});

		it('should find data header row correctly', () => {
			const csv = `American Express Card
Transaction Details
Account Summary
Summary
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store,$100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].vendor_name).toBe('Test Store');
		});

		it('should handle extra columns after required ones', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// The sample file has additional columns like Foreign Spend Amount, Commission, etc.
			// Parser should handle these gracefully
			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(14);
		});

		it('should trim whitespace from vendor names', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,  Test Store  ,$100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].vendor_name).toBe('Test Store');
		});

		it('should handle different vendor name formats', () => {
			const csv = loadCSV('Amex-Test.csv');
			const result = parser.parse(csv);

			// Check various vendor name formats from the sample
			const vendorNames = result.transactions.map((t) => t.vendor_name);
			expect(vendorNames).toContain('Alcohol');
			expect(vendorNames).toContain('Grocery 1');
			expect(vendorNames).toContain('Resturant 1');
			expect(vendorNames).toContain('Hardware store');
		});

		it('should handle integer amounts without decimals', () => {
			const csv = `American Express
,,,,
Date,Date Processed,Description,Amount,Foreign Spend Amount
31-May-25,01 Jun. 2025,Test Store,$100,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-100);
		});
	});
});

