import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { RBCFinancialParser } from '../RBCFinancialParser';

describe('RBCFinancialParser', () => {
	const parser = new RBCFinancialParser();

	// Helper to load CSV files from resources
	const loadCSV = (filename: string): string => {
		const filePath = join(process.cwd(), 'resources', filename);
		return readFileSync(filePath, 'utf-8');
	};

	describe('validateFormat', () => {
		it('should validate correct RBC Financial CSV format', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should reject invalid CSV format', () => {
			const invalidCSV = `Date,Merchant,Amount
01/01/2024,Store,100.00`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should reject empty CSV', () => {
			expect(parser.validateFormat('')).toBe(false);
		});

		it('should reject CSV with too few columns', () => {
			const invalidCSV = `"Account Type","Account Number","Transaction Date"
Visa,4514015001949444,6/10/2024`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});
	});

	describe('parse', () => {
		it('should parse sample data correctly (#{#trn2d})', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(2);

			// Check first transaction (expense, stays negative)
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-06-10',
				vendor_name: 'PEACE HILLS INSURANCE 780-424-3986 AB',
				amount: -2445.0 // -2445.00 (expense), negative = expense
			});

			// Check second transaction (credit, stays positive)
			expect(result.transactions[1]).toEqual({
				transaction_date: '2024-06-25',
				vendor_name: 'CIBC TORONTO',
				amount: 315.9 // 315.90 (credit), positive = refund
			});
		});

		it('should keep expenses as negative amounts (#{#trn2d})', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			const result = parser.parse(csv);
			expect(result.transactions[0].amount).toBe(-2445.0); // Expense stays negative
		});

		it('should keep credits as positive amounts (#{#trn2d})', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			const result = parser.parse(csv);
			expect(result.transactions[1].amount).toBe(315.9); // Credit stays positive
		});

		it('should parse dates in M/D/YYYY format', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,12/31/2023,,"Test Store",,-100.00,,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2023-12-31');
		});

		it('should handle dates with single digit month/day', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,1/5/2024,,"Test Store",,-50.00,,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-01-05');
		});

		it('should combine Description 1 and Description 2', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,6/10/2024,,"Store Name","Location Info",-100.00,,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].vendor_name).toBe('Store Name Location Info');
		});

		it('should handle Description 1 only', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			const result = parser.parse(csv);
			expect(result.transactions[1].vendor_name).toBe('CIBC TORONTO');
		});

		it('should report errors for invalid dates', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,invalid-date,,"Test Store",,-100.00,,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid date format');
		});

		it('should report errors for invalid amounts', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,6/10/2024,,"Test Store",,not-a-number,,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should report errors for missing vendor name', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,6/10/2024,,,,-100.00,,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Missing vendor name');
		});

		it('should handle empty CSV', () => {
			const result = parser.parse('');

			expect(result.transactions).toEqual([]);
			expect(result.errors.length).toBeGreaterThan(0);
		});

		it('should skip incomplete rows', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,6/10/2024,,"Test Store",,-100.00,,
Incomplete Row
Visa,4514015001949444,6/11/2024,,"Another Store",,-50.00,,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.transactions[0].vendor_name).toBe('Test Store');
			expect(result.transactions[1].vendor_name).toBe('Another Store');
		});

		it('should skip empty rows', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,6/10/2024,,"Test Store",,-100.00,,

Visa,4514015001949444,6/11/2024,,"Another Store",,-50.00,,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.errors).toEqual([]);
		});

		it('should handle quoted fields correctly', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
"Visa","4514015001949444","6/10/2024",,"Test, Store",,-100.00,,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].vendor_name).toBe('Test, Store');
		});

		it('should keep expense amounts with decimals as negative (#{#trn2d})', () => {
			const csv = loadCSV('RBCFinancialSample.csv');
			const result = parser.parse(csv);
			expect(result.transactions[0].amount).toBe(-2445.0); // Expense stays negative
		});

		it('should keep expense integer amounts as negative (#{#trn2d})', () => {
			const csv = `"Account Type","Account Number","Transaction Date","Cheque Number","Description 1","Description 2","CAD$","USD$"
Visa,4514015001949444,6/10/2024,,"Test Store",,-100,,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-100); // Expense stays negative
		});
	});
});

