import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { SimpliiFinancialParser } from '../SimpliiFinancialParser';

describe('SimpliiFinancialParser', () => {
	const parser = new SimpliiFinancialParser();

	// Helper to load CSV files from resources
	const loadCSV = (filename: string): string => {
		const filePath = join(process.cwd(), 'resources', filename);
		return readFileSync(filePath, 'utf-8');
	};

	describe('validateFormat', () => {
		it('should validate correct Simplii Financial CSV format', () => {
			const csv = loadCSV('SIMPLII.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should reject invalid CSV format', () => {
			const invalidCSV = `Date,Description,Amount
01/01/2024,Store,100.00`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should reject empty CSV', () => {
			expect(parser.validateFormat('')).toBe(false);
		});

		it('should reject CSV without required columns', () => {
			const invalidCSV = `Date, Transaction Details
07/25/2024,MISCELLANEOUS PAYMENTS`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('SIMPLII.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});
	});

	describe('parse', () => {
		it('should parse sample data correctly (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(38);

			// Check first transaction (Funds Out, stays negative)
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-07-25',
				vendor_name: 'MISCELLANEOUS PAYMENTS PCF PAD W/D CHEQUE',
				amount: -1852.64 // Funds Out (expense), negative = expense
			});

			// Check a transaction with Funds In (stays positive)
			expect(result.transactions[2]).toEqual({
				transaction_date: '2024-07-29',
				vendor_name: 'CHEQUE IMAGE DEPOSIT',
				amount: 1249.23 // Funds In (deposit), positive = refund/deposit
			});
		});

		it('should keep Funds Out (expenses) as negative amounts (#{#trn2f})', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Payment,100.50,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(-100.5); // Expense stays negative
		});

		it('should keep Funds In (deposits) as positive amounts (#{#trn2f})', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/29/2024,Test Deposit,,250.75`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(250.75); // Deposit stays positive
		});

		it('should parse dates in MM/DD/YYYY format', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
12/31/2023,Test Transaction,100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2023-12-31');
		});

		it('should handle dates with single digit month/day', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
1/5/2024,Test Transaction,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-01-05');
		});

		it('should handle transaction details with leading spaces', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			// Sample file has transactions like " INTERAC E-TRANSFER SEND"
			const interacTransactions = result.transactions.filter((t) =>
				t.vendor_name.includes('INTERAC E-TRANSFER')
			);
			expect(interacTransactions.length).toBeGreaterThan(0);
		});

		it('should handle various transaction types', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			const transactionTypes = result.transactions.map((t) => t.vendor_name);
			expect(transactionTypes.some((t) => t.includes('PAYROLL DEPOSIT'))).toBe(true);
			expect(transactionTypes.some((t) => t.includes('INTERAC E-TRANSFER'))).toBe(true);
			expect(transactionTypes.some((t) => t.includes('BILL PAYMENT'))).toBe(true);
			expect(transactionTypes.some((t) => t.includes('INTEREST'))).toBe(true);
		});

		it('should keep expense amounts without decimals as negative (#{#trn2f})', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,100,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-100); // Expense stays negative
		});

		it('should report errors for invalid dates', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
invalid-date,Test Transaction,100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid date format');
		});

		it('should report errors for invalid amounts', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,not-a-number,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should report errors for missing transaction details', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,,100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Missing transaction details');
		});

		it('should report errors when both Funds Out and Funds In are empty', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should handle empty CSV', () => {
			const result = parser.parse('');

			expect(result.transactions).toEqual([]);
			expect(result.errors.length).toBeGreaterThan(0);
		});

		it('should skip incomplete rows', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,100.00,
Incomplete Row
07/26/2024,Another Transaction,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.transactions[0].vendor_name).toBe('Test Transaction');
			expect(result.transactions[1].vendor_name).toBe('Another Transaction');
		});

		it('should skip empty rows', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,100.00,

07/26/2024,Another Transaction,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
		});

		it('should handle CSV with BOM', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(38);
			expect(result.errors).toEqual([]);
		});

		it('should trim whitespace from transaction details', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,  Test Transaction  ,100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].vendor_name).toBe('Test Transaction');
		});

		it('should keep large expense amounts as negative (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			// Check for large transaction amounts (expenses stay negative)
			const largeTransaction = result.transactions.find((t) =>
				t.vendor_name.includes('MISCELLANEOUS PAYMENTS EQUITABLE BANK')
			);
			expect(largeTransaction).toBeDefined();
			expect(largeTransaction!.amount).toBe(-10000.0); // Expense stays negative
		});

		it('should keep Funds Out (expenses) as negative amounts (#{#trn2f})', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBeLessThan(0); // Expense stays negative
		});

		it('should keep Funds In (deposits) as positive amounts (#{#trn2f})', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Test Transaction,,100.00`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBeGreaterThan(0); // Deposit stays positive
		});

		it('should handle mixed Funds Out and Funds In transactions (#{#trn2f})', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,Payment,100.00,
07/26/2024,Deposit,,200.00
07/27/2024,Withdrawal,50.00,
07/28/2024,Credit,,75.00`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(4);
			expect(result.transactions[0].amount).toBe(-100.0); // Expense stays negative
			expect(result.transactions[1].amount).toBe(200.0); // Deposit stays positive
			expect(result.transactions[2].amount).toBe(-50.0); // Expense stays negative
			expect(result.transactions[3].amount).toBe(75.0); // Deposit stays positive
		});

		it('should handle transactions with commas in details', () => {
			const csv = `Date, Transaction Details, Funds Out, Funds In
07/25/2024,"PAYMENT TO VENDOR, INC.",100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].vendor_name).toBe('PAYMENT TO VENDOR, INC.');
		});

		it('should keep payroll deposits as positive amounts (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			const payrollTransactions = result.transactions.filter((t) =>
				t.vendor_name.includes('PAYROLL DEPOSIT')
			);
			expect(payrollTransactions.length).toBeGreaterThan(0);
			expect(payrollTransactions.every((t) => t.amount > 0)).toBe(true); // Deposits stay positive
		});

		it('should keep bill payments as negative amounts (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			const billPayments = result.transactions.filter((t) =>
				t.vendor_name.includes('BILL PAYMENT')
			);
			expect(billPayments.length).toBeGreaterThan(0);
			expect(billPayments.every((t) => t.amount < 0)).toBe(true); // Expenses stay negative
		});

		it('should keep interest transactions as positive amounts (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			const interestTransactions = result.transactions.filter((t) =>
				t.vendor_name.includes('INTEREST')
			);
			expect(interestTransactions.length).toBeGreaterThan(0);
			expect(interestTransactions.every((t) => t.amount > 0)).toBe(true); // Deposits stay positive
		});

		it('should handle Interac e-transfers correctly (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			const sendTransactions = result.transactions.filter((t) =>
				t.vendor_name.includes('INTERAC E-TRANSFER SEND')
			);
			const receiveTransactions = result.transactions.filter((t) =>
				t.vendor_name.includes('INTERAC E-TRANSFER RECEIVE')
			);

			expect(sendTransactions.length).toBeGreaterThan(0);
			expect(receiveTransactions.length).toBeGreaterThan(0);
			expect(sendTransactions.every((t) => t.amount < 0)).toBe(true); // Sent → negative (expense)
			expect(receiveTransactions.every((t) => t.amount > 0)).toBe(true); // Received → positive (deposit)
		});

		it('should keep transfer out transactions as negative amounts (#{#trn2f})', () => {
			const csv = loadCSV('SIMPLII.csv');
			const result = parser.parse(csv);

			const transferTransactions = result.transactions.filter((t) =>
				t.vendor_name.includes('TRANSFER OUT')
			);
			expect(transferTransactions.length).toBeGreaterThan(0);
			expect(transferTransactions.every((t) => t.amount < 0)).toBe(true); // Transfers out stay negative (expense)
		});
	});
});

