import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';
import { EQBankParser } from '../EQBankParser';

describe('EQBankParser', () => {
	const parser = new EQBankParser();

	// Helper to load CSV files from resources
	const loadCSV = (filename: string): string => {
		const filePath = join(process.cwd(), 'resources', filename);
		return readFileSync(filePath, 'utf-8');
	};

	describe('validateFormat', () => {
		it('should validate correct EQ Bank Card CSV format', () => {
			const csv = loadCSV('EQ Bank Bank Card.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should validate correct EQ Bank Primary Account CSV format', () => {
			const csv = loadCSV('EQ Bank Primary Account.csv');
			expect(parser.validateFormat(csv)).toBe(true);
		});

		it('should accept Date or Transfer date column', () => {
			const csvWithTransferDate = `Transfer date,Description,Amount
30 Nov 2024,Test Transaction,$10.00`;
			expect(parser.validateFormat(csvWithTransferDate)).toBe(true);

			const csvWithDate = `Date,Description,Amount
30 Nov 2024,Test Transaction,$10.00`;
			expect(parser.validateFormat(csvWithDate)).toBe(true);
		});

		it('should reject invalid CSV format', () => {
			const invalidCSV = `Description,Type,Card Holder Name,Date,Time,Amount
Test Store,PURCHASE,MARK,06/01/2024,11:59 PM,-100.00`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});

		it('should reject empty CSV', () => {
			expect(parser.validateFormat('')).toBe(false);
		});

		it('should reject CSV without required columns', () => {
			const invalidCSV = `Date,Description
30 Nov 2024,Test Transaction`;
			expect(parser.validateFormat(invalidCSV)).toBe(false);
		});
	});

	describe('parse - Bank Card format', () => {
		it('should parse bank card CSV correctly (#{#trn2b})', () => {
			const csv = loadCSV('EQ Bank Bank Card.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(2);

			// Check first transaction (deposit, stays positive)
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-12-06',
				vendor_name: 'Cashback',
				amount: 0.1 // $0.10 (deposit), negative = expense
			});

			// Check second transaction (expense with parentheses, stays negative)
			expect(result.transactions[1]).toEqual({
				transaction_date: '2024-11-15',
				vendor_name: 'Random Vendor',
				amount: -25.0 // ($25.00) (expense), negative = expense
			});
		});

		it('should keep deposits as positive amounts (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Deposit,$100.50`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(100.5); // Deposit stays positive
		});

		it('should keep expenses as negative amounts (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Purchase,($50.25)`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-50.25); // Expense stays negative
		});
	});

	describe('parse - Primary Account format', () => {
		it('should parse primary account CSV correctly (#{#trn2b})', () => {
			const csv = loadCSV('EQ Bank Primary Account.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(9);

			// Check first transaction (deposit, stays positive)
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-11-30',
				vendor_name: 'Account Credited from XYXZ',
				amount: 2.05 // $2.05 (deposit), stays positive
			});

			// Check transaction with comma in amount (deposit, stays positive)
			expect(result.transactions[2]).toEqual({
				transaction_date: '2024-11-28',
				vendor_name: 'Direct deposit from Mother corp',
				amount: 2543.6 // $2,543.60 (deposit), stays positive
			});

			// Check expense transaction (stays negative)
			expect(result.transactions[4]).toEqual({
				transaction_date: '2024-11-25',
				vendor_name: 'Auto-withdrawal by PCF PAD W D',
				amount: -992.93 // ($992.93) (expense), stays negative
			});
		});

		it('should keep deposits with commas as positive amounts (#{#trn2b})', () => {
			const csv = `Transfer date,Description,Amount,Balance
30 Nov 2024,Large Deposit,"$2,543.60",`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(2543.6); // Deposit stays positive
		});

		it('should ignore Balance column and keep deposit amounts positive (#{#trn2b})', () => {
			const csv = `Transfer date,Description,Amount,Balance
30 Nov 2024,Test Transaction,$10.00,$1000.00`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(10.0); // Deposit stays positive
		});
	});

	describe('parse - Date formats', () => {
		it('should parse DD MMM YYYY format', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,$10.00
15 Nov 2024,Another Transaction,$20.00
01 Jan 2024,New Year Transaction,$30.00`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-12-06');
			expect(result.transactions[1].transaction_date).toBe('2024-11-15');
			expect(result.transactions[2].transaction_date).toBe('2024-01-01');
		});

		it('should parse DD Mon YYYY format (full month name)', () => {
			const csv = `Date,Description,Amount
06 December 2024,Test Transaction,$10.00`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-12-06');
		});

		it('should report errors for invalid dates', () => {
			const csv = `Date,Description,Amount
invalid-date,Test Transaction,$10.00`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid date format');
		});

		it('should parse YYYY-MM-DD format (new EQ Bank format)', () => {
			const csv = `Date,Description,Amount
2024-12-06,Test Transaction,$10.00
2025-10-31,Another Transaction,$20.00
2024-01-01,New Year Transaction,$30.00`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-12-06');
			expect(result.transactions[1].transaction_date).toBe('2025-10-31');
			expect(result.transactions[2].transaction_date).toBe('2024-01-01');
		});

		it('should parse new format EQ Bank Primary Account CSV (#{#trn2b})', () => {
			const csv = loadCSV('EQ Bank Primary Account New Format.csv');
			const result = parser.parse(csv);

			expect(result.errors).toEqual([]);
			expect(result.transactions).toHaveLength(9);

			// Check first transaction with new date format (deposit, stays positive)
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-11-30',
				vendor_name: 'Account Credited from XYXZ',
				amount: 2.05 // $2.05 (deposit), stays positive
			});

			// Check transaction with comma in amount (deposit, stays positive)
			expect(result.transactions[2]).toEqual({
				transaction_date: '2024-11-28',
				vendor_name: 'Direct deposit from Mother corp',
				amount: 2543.6 // $2,543.60 (deposit), stays positive
			});

			// Check expense transaction (stays negative)
			expect(result.transactions[4]).toEqual({
				transaction_date: '2024-11-25',
				vendor_name: 'Auto-withdrawal by PCF PAD W D',
				amount: -992.93 // ($992.93) (expense), stays negative
			});
		});

		it('should handle both old and new date formats in same parser', () => {
			const csvOldFormat = `Date,Description,Amount
06 Dec 2024,Old Format Transaction,$10.00`;
			const csvNewFormat = `Date,Description,Amount
2024-12-06,New Format Transaction,$20.00`;

			const resultOld = parser.parse(csvOldFormat);
			const resultNew = parser.parse(csvNewFormat);

			expect(resultOld.transactions[0].transaction_date).toBe('2024-12-06');
			expect(resultNew.transactions[0].transaction_date).toBe('2024-12-06');
			expect(resultOld.errors).toEqual([]);
			expect(resultNew.errors).toEqual([]);
		});
	});

	describe('parse - Amount formats', () => {
		it('should keep deposits without dollar sign as positive (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,10.00`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(10.0); // Deposit stays positive
		});

		it('should keep deposits with dollar sign as positive (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,$10.00`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(10.0); // Deposit stays positive
		});

		it('should keep expenses with parentheses as negative (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,($10.00)`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-10.0); // Expense stays negative
		});

		it('should keep deposits with commas as positive (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,"$1,234.56"`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(1234.56); // Deposit stays positive
		});

		it('should keep expenses with parentheses and commas as negative (#{#trn2b})', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,"($1,234.56)"`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-1234.56); // Expense stays negative
		});

		it('should report errors for invalid amounts', () => {
			const csv = `Date,Description,Amount
06 Dec 2024,Test Transaction,not-a-number`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		// EQ Bank's CSV export wraps both description and amount values in extra
		// quotes, producing triple-quoted fields like `"""-$33.00"""`. The standard
