		});

		it('should keep credit transactions as positive amounts (#{#trn2e})', () => {
			const csv = `06/11/2024,Store 1,,23.15`;
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0]).toEqual({
				transaction_date: '2024-06-11',
				vendor_name: 'Store 1',
				amount: 23.15 // Credit stays positive
			});
		});

		it('should keep debit amounts without decimals as negative (#{#trn2e})', () => {
			const csv = `06/24/2024,Store C,85,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].amount).toBe(-85); // Debit stays negative
		});

		it('should parse dates in MM/DD/YYYY format', () => {
			const csv = `12/31/2023,Test Store,100.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2023-12-31');
		});

		it('should handle dates with single digit month/day', () => {
			const csv = `1/5/2024,Test Store,50.00,`;
			const result = parser.parse(csv);

			expect(result.transactions[0].transaction_date).toBe('2024-01-05');
		});

		it('should report errors for invalid dates', () => {
			const csv = `invalid-date,Test Store,100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid date format');
		});

		it('should report errors for invalid amounts', () => {
			const csv = `06/01/2024,Test Store,not-a-number,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Invalid amount');
		});

		it('should report errors for missing vendor name', () => {
			const csv = `06/01/2024,,100.00,`;
			const result = parser.parse(csv);

			expect(result.errors.length).toBeGreaterThan(0);
			expect(result.errors[0]).toContain('Missing vendor name');
		});

